 while(!service.complete()&&service.request()==T::Request::None){const auto cost=service.nextClocks(previous);check(cost>0,"Scene cost stalled");std::array<unsigned char,sizeof(T)>before{};std::memcpy(before.data(),&service,sizeof(T));unsigned effects=0;tracking=true;const auto bad=service.advanceBefore(cost-1,[&](uint32_t,unsigned){++effects;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++effects;},previous);tracking=false;check(!bad&&!effects&&!std::memcmp(before.data(),&service,sizeof(T)),"Rejected Scene budget changed job");++rejected;tracking=true;const auto used=service.advanceBefore(cost,[&](uint32_t a,unsigned dt){check(dt<=cost&&dt>0,"Scene read timing");++reads;return m[a];},[&](uint32_t a,uint8_t v,unsigned dt){check(dt<=cost&&dt>0,"Scene write timing");++writes;m[a]=v;previous=history(a);},previous);tracking=false;check(used==cost,"Scene phase budget");if(service.effect().write)previous=-1;components|=service.components();maxDepth=std::max(maxDepth,service.depth());check(++steps<300000,"Scene graph stalled");++phases;}
