for(uint32_t bad:{0u,0x5006u,0xfff000u,0x80fff700u,0xffff51u}){std::fill(m.begin(),m.end(),0);T::Input in;in.nameTarget=bad;T s(T::Kind::CommitName,in);bool threw=false;unsigned writeCount=0;while(!threw&&s.request()==T::Request::None&&!s.complete()){const auto cost=s.nextClocks();try{s.advanceBefore(cost,[&](uint32_t a,unsigned){return m[a];},[&](uint32_t a,uint8_t v,unsigned){++writeCount;m[a]=v;});}catch(const std::logic_error&){threw=true;}}check(threw&&!writeCount,"SceneEdit actual name target guard");++guardCases;}
